t.script:
                document.addEventListener("DOMContentLoaded", function() {
                    const canvas = document.getElementById("signature-canvas");
                    const form = document.getElementById("signature-form");
                    const signatureInput = document.getElementById("signature-input");
                    const clearButton = document.getElementById("clear-signature");
                    const ctx = canvas.getContext("2d");

                    // Ajustar la resolución interna del canvas a su tamaño en pantalla
                    function resizeCanvas() {
                        const rect = canvas.getBoundingClientRect();
                        canvas.width = rect.width;
                        canvas.height = rect.height;
                        // Estilos del trazo
                        ctx.strokeStyle = "#000000";
                        ctx.lineWidth = 3;
                        ctx.lineJoin = "round";
                        ctx.lineCap = "round";
                    }
                    
                    resizeCanvas();
                    window.addEventListener("resize", resizeCanvas);

                    let drawing = false;
                    let lastX = 0;
                    let lastY = 0;
                    let hasDrawn = false;

                    // Obtener coordenadas corregidas (soporta Mouse y Touch)
                    function getPos(e) {
                        const rect = canvas.getBoundingClientRect();
                        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
                        const clientY = e.touches ? e.touches[0].clientY : e.clientY;
                        return {
                            x: clientX - rect.left,
                            y: clientY - rect.top
                        };
                    }

                    function startDrawing(e) {
                        drawing = true;
                        const pos = getPos(e);
                        lastX = pos.x;
                        lastY = pos.y;
                    }

                    function draw(e) {
                        if (!drawing) return;
                        // Evita que la pantalla se mueva/haga scroll en celulares mientras firmas
                        if (e.touches) e.preventDefault(); 
                        
                        const pos = getPos(e);
                        
                        ctx.beginPath();
                        ctx.moveTo(lastX, lastY);
                        ctx.lineTo(pos.x, pos.y);
                        ctx.stroke();
                        
                        lastX = pos.x;
                        lastY = pos.y;
                        hasDrawn = true;
                    }

                    function stopDrawing() {
                        drawing = false;
                    }

                    // Eventos para Mouse (Escritorio)
                    canvas.addEventListener("mousedown", startDrawing);
                    canvas.addEventListener("mousemove", draw);
                    window.addEventListener("mouseup", stopDrawing);

                    // Eventos para Touch (Móviles / Tablets)
                    canvas.addEventListener("touchstart", startDrawing, { passive: false });
                    canvas.addEventListener("touchmove", draw, { passive: false });
                    window.addEventListener("touchend", stopDrawing);

                    // Acción del botón Limpiar
                    clearButton.addEventListener("click", function() {
                        ctx.clearRect(0, 0, canvas.width, canvas.height);
                        hasDrawn = false;
                        signatureInput.value = "";
                    });

                    // Antes de enviar el formulario por POST
                    form.addEventListener("submit", function(e) {
                        if (!hasDrawn) {
                            e.preventDefault();
                            alert("Por favor, firme el recibo antes de confirmar.");
                            return;
                        }
                        // Convierte el Canvas a formato DataURL (data:image/png;base64,...)
                        const dataUrl = canvas.toDataURL("image/png");
                        // Odoo necesita el Base64 PURO para guardarlo en un campo Binary. 
                        // Quitamos el prefijo "data:image/png;base64," usando split:
                        signatureInput.value = dataUrl.split(',')[1];
                    });
                });
